const chatModule = {
  state: {
    recentChats: [], // 最近聊天列表
  },
  mutations: {
    // 更新最近聊天列表
    UPDATE_RECENT_CHATS(state, user) {
      // 检查用户是否已在列表中
      const existingIndex = state.recentChats.findIndex(
        (item) => item.id === user.id
      );
      if (existingIndex !== -1) {
        // 如果存在，移到列表顶部
        state.recentChats.splice(existingIndex, 1);
        state.recentChats.unshift(user);
      } else {
        // 如果不存在，添加到列表顶部
        state.recentChats.unshift(user);
      }
    },
    // 从 localStorage 初始化最近聊天列表
    INIT_RECENT_CHATS(state) {
      const recentChats = localStorage.getItem('recentChats');
      if (recentChats) {
        state.recentChats = JSON.parse(recentChats);
      }
    },
  },
  actions: {
    // 保存最近聊天列表到 localStorage
    saveRecentChats({ state }) {
      localStorage.setItem('recentChats', JSON.stringify(state.recentChats));
    },
  },
  getters: {
    getRecentChats: (state) => state.recentChats,
  },
};

export default chatModule;
